/**
 * Custom Cloudflare Worker entry.
 *
 * - fetch:     the Next.js app, built by `opennextjs-cloudflare build`
 *              into .open-next/worker.js
 * - queue:     PushKit campaign fan-out consumer (batches of 40 subscribers)
 * - scheduled: PushKit cron (scheduled campaigns, RSS polling, daily purge)
 *
 * wrangler.toml points `main` here, so a single `npm run deploy`
 * ships the app, the queue consumer, and the cron engine in one Worker.
 */
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore — generated by `opennextjs-cloudflare build`; absent on a fresh clone, present after a build.
import openNextWorker from "./.open-next/worker.js";
import type { CloudflareEnv, D1DatabaseLike } from "./src/lib/bindings";
import { runCron } from "./src/lib/cron";
import { deliverBatch } from "./src/lib/push/fanout";
import { D1Store } from "./src/lib/store";
import type { PushBatchMessage } from "./src/lib/types";

interface QueueMessage {
  body: PushBatchMessage;
  ack(): void;
  retry(): void;
}

interface Env extends CloudflareEnv {
  DB: D1DatabaseLike;
}

const worker = {
  fetch: async (request: Request, env: unknown, ctx: unknown): Promise<Response> => {
    const errorLogs: string[] = [];
    const origError = console.error;
    console.error = (...args: unknown[]) => {
      try {
        errorLogs.push(
          args
            .map((a) =>
              a instanceof Error
                ? `${a.name}: ${a.message}\n${a.stack}`
                : typeof a === "object"
                  ? JSON.stringify(a)
                  : String(a)
            )
            .join(" ")
        );
      } catch {
        // ignore format error
      }
      origError.apply(console, args as [unknown, ...unknown[]]);
    };

    try {
      const response = await (
        openNextWorker as {
          fetch: (request: Request, env: unknown, ctx: unknown) => Promise<Response>;
        }
      ).fetch(request, env, ctx);

      // If Next.js returned a 500 error and logged error details, surface them in response for quick diagnosis.
      if (response.status === 500 && errorLogs.length > 0) {
        return new Response(
          `PushKit Server Error Details:\n\n${errorLogs.join("\n\n---\n\n")}`,
          {
            status: 500,
            headers: { "content-type": "text/plain; charset=utf-8" },
          }
        );
      }
      return response;
    } catch (err: unknown) {
      const e = err as Error;
      return new Response(
        `PushKit Application Error\n\n${e?.name || "Error"}: ${e?.message || String(e)}\n\n${e?.stack || ""}\n\nLogs:\n${errorLogs.join("\n")}`,
        {
          status: 500,
          headers: { "content-type": "text/plain; charset=utf-8" },
        }
      );
    } finally {
      console.error = origError;
    }
  },

  async queue(batch: { messages: QueueMessage[] }, env: Env): Promise<void> {
    const store = new D1Store(env.DB);
    for (const message of batch.messages) {
      try {
        await deliverBatch(store, message.body);
        message.ack();
      } catch {
        message.retry();
      }
    }
  },

  async scheduled(event: { cron: string }, env: Env): Promise<void> {
    const store = new D1Store(env.DB);
    await runCron(store, event.cron);
  },
};

export default worker;
